'use strict';

// MODULES //

var tape = require( 'tape' );
var isSymbolShorthand = require( '@stdlib/plot/base/assert/is-symbol-shorthand' );
var symbolShorthands = require( '@stdlib/plot/base/symbol-shorthands' );
var symbolAliases = require( '@stdlib/plot/base/symbol-aliases' );
var symbol2shorthand = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof symbol2shorthand, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a shorthand when provided a symbol alias', function test( t ) {
	var values;
	var v;
	var i;

	values = symbolAliases();
	for ( i = 0; i < values.length; i++ ) {
		v = symbol2shorthand( values[ i ] );
		t.strictEqual( isSymbolShorthand( v ), true, 'returns expected value for ' + values[ i ] );
	}
	t.end();
});

tape( 'the function returns the provided shorthand when provided a symbol shorthand', function test( t ) {
	var values;
	var v;
	var i;

	values = symbolShorthands();
	for ( i = 0; i < values.length; i++ ) {
		v = symbol2shorthand( values[ i ] );
		t.strictEqual( v, values[ i ], 'returns expected value for ' + values[ i ] );
	}
	t.end();
});

tape( 'the function resolves the same shorthand for a symbol alias and its corresponding shorthand', function test( t ) {
	t.strictEqual( symbol2shorthand( 'circle' ), 'o', 'returns expected value' );
	t.strictEqual( symbol2shorthand( 'o' ), 'o', 'returns expected value' );
	t.end();
});

tape( 'the function resolves the same shorthand for each accepted alias of a symbol', function test( t ) {
	t.strictEqual( symbol2shorthand( 'plus' ), symbol2shorthand( 'cross' ), 'returns expected value' );
	t.strictEqual( symbol2shorthand( 'pentagram' ), symbol2shorthand( 'star' ), 'returns expected value' );
	t.end();
});

tape( 'if unable to resolve a shorthand, the function returns `null`', function test( t ) {
	var expected;
	var actual;
	var values;
	var i;

	values = [
		'',
		'beep',
		'boop',
		'==',
		'toString',
		'constructor'
	];
	expected = null;
	for ( i = 0; i < values.length; i++ ) {
		actual = symbol2shorthand( values[ i ] );
		t.strictEqual( actual, expected, 'returns expected value for ' + values[ i ] );
	}
	t.end();
});
